// ============================================================
// 用「判别联合 + 类型收窄 + 穷尽检查」建模一次 API 请求的完整生命周期
// 可直接用 npx tsx 运行
// ============================================================

// 1. 判别联合：用 status 的字符串字面量类型作为「判别式」
type RequestState<T> =
  | { status: 'idle' }
  | { status: 'loading'; startedAt: number }
  | { status: 'success'; data: T; duration: number }
  | { status: 'error'; error: Error; retryCount: number };

// 2. 穷尽检查的基石：assertNever
// 参数类型是 never，意味着「永远不该被调用」
function assertNever(x: never): never {
  throw new Error(`未处理的分支: ${JSON.stringify(x)}`);
}

// 3. 自定义类型守卫：is 关键字让调用方也能收窄
// 注意：is 右侧必须是入参类型的子类型
function isSuccess<T>(
  state: RequestState<T>,
): state is Extract<RequestState<T>, { status: 'success' }> {
  return state.status === 'success';
}

// 4. 通用的非空守卫（处理来自外部的 unknown / null 数据）
function isDefined<T>(value: T | null | undefined): value is T {
  return value !== null && value !== undefined;
}

// 5. 核心：switch + default 调用 assertNever 实现编译期穷尽检查
function describe<T>(state: RequestState<T>): string {
  switch (state.status) {
    case 'idle':
      return '尚未发起请求';
    case 'loading':
      // 收窄后 startedAt 可直接访问，无需可选链
      return `加载中…（${Date.now() - state.startedAt}ms）`;
    case 'success':
      return `成功，耗时 ${state.duration}ms`;
    case 'error':
      return `失败（第 ${state.retryCount + 1} 次尝试），原因：${state.error.message}`;
    default:
      // 如果未来新增了 status 分支却没写 case，这里会编译报错
      return assertNever(state);
  }
}

// 6. 实战：用「结果类型」取代「抛异常 + 可能为 null」
type Result<T, E> =
  | { ok: true; value: T }
  | { ok: false; error: E };

interface User {
  id: number;
  name: string;
}

function fetchUser(id: number): Result<User, Error> {
  if (!Number.isInteger(id) || id <= 0) {
    return { ok: false, error: new Error(`非法的用户 ID: ${id}`) };
  }
  return { ok: true, value: { id, name: `用户#${id}` } };
}

// ---- 演示 ----
const states: RequestState<User>[] = [
  { status: 'idle' },
  { status: 'loading', startedAt: Date.now() - 120 },
  { status: 'success', data: { id: 7, name: 'Mika' }, duration: 86 },
  { status: 'error', error: new Error('Network timeout'), retryCount: 1 },
];

for (const s of states) {
  console.log(describe(s));
  // 类型守卫在「if 之外」同样生效，是零成本的运行时收窄
  if (isSuccess(s)) {
    console.log('  → 只有进入这个分支，s.data 才是可用的：', s.data.name);
  }
}

// Result 风格：调用方被强制处理失败分支
for (const id of [7, -1]) {
  const r = fetchUser(id);
  if (!r.ok) {
    console.log(`读取失败：${r.error.message}`);
    continue;
  }
  console.log(`读取成功：${r.value.name}`);
}

// isDefined 的典型用法：过滤数组中的空值并保留类型
const maybeNames: (string | null | undefined)[] = ['Ada', null, 'Lin', undefined, 'Kay'];
const names: string[] = maybeNames.filter(isDefined);
console.log(names); // ['Ada', 'Lin', 'Kay']

