type State =
  | { status: 'loading' }
  | { status: 'success'; data: string };

function isSuccess(s: State): ______ {
  return s.status === 'success';
}

const s: State = { status: 'success', data: 'hi' };
if (isSuccess(s)) {
  console.log(s.data.toUpperCase()); // 希望这里不报错
}

function assertNever(x: never): never {
  throw new Error(`未处理的分支: ${JSON.stringify(x)}`);
}

switch (state.status) {
  case 'idle': return 'a';
  case 'loading': return 'b';
  default: return assertNever(state);
}

type Event =
  | { type: 'click'; x: number }
  | { type: 'scroll'; dy: number };

function handle(e: Event): string {
  switch (e.type) {
    case 'click':
      return `click@${e.x}`;
    case 'scroll':
      return `scroll${e.dy}`;
    default:
      return 'unknown';
  }
}

console.log(handle({ type: 'click', x: 10 }));
console.log(handle({ type: 'scroll', dy: 5 }));

const raw: any = { type: 'dblclick', x: 1 };
console.log(handle(raw));
